def explain(sid):
    s=BY_ID[sid]
    definition, rising, falling, caution=GUIDE[sid]
    return {**metadata(s),'frequency_label':FREQ[s.freq], 'definition':definition,'rising':rising,'falling':falling,'caution':caution}
